#!/usr/bin/env python3
"""Generate P04 classification tables from the pinned HF wheel, without fixtures."""
import hashlib
import json
from pathlib import Path
import subprocess
import tokenizers
from tokenizers import Regex, pre_tokenizers as pt

ROOT = Path(__file__).resolve().parents[2]


def sha(data):
    return hashlib.sha256(data).hexdigest()


def main():
    assert tokenizers.__version__ == '0.22.2'
    scalars = ''.join(chr(c) for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF)
    ranges = []
    # Disjoint classes: A=Lu|Lt|Lm|Lo|M, B=Ll|Lm|Lo|M.
    for mask, expr in [(1, r'[\p{Lu}\p{Lt}]+'), (2, r'\p{Ll}+'),
                       (3, r'[\p{Lm}\p{Lo}\p{M}]+')]:
        splitter = pt.Split(Regex(expr), 'removed', invert=True)
        ranges.extend((ord(s[0]), ord(s[-1]), mask)
                      for s, _ in splitter.pre_tokenize_str(scalars))
    ranges.sort()
    assert all(a[1] < b[0] for a, b in zip(ranges, ranges[1:]))
    lines = ['// Code generated by testdata/patterns/generate_case_tables.py; DO NOT EDIT.',
             '// Unicode membership pinned to tokenizers 0.22.2 native oracle.',
             'package scan', '', 'var caseWordRanges = [...]caseRange{']
    lines += ['{0x%X, 0x%X, %d},' % r for r in ranges]
    lines += ['}', '']
    table = ROOT / 'internal/scan/case_tables.go'
    table.write_text('\n'.join(lines))
    subprocess.run(['gofmt', '-w', str(table)], check=True)
    path = ROOT / 'testdata/patterns/P04/manifest.json'
    manifest = json.loads(path.read_text())
    manifest.update(oracle_native_sha256=sha((Path(tokenizers.__file__).parent/'tokenizers.abi3.so').read_bytes()),
                    tables_sha256=sha(table.read_bytes()), generator_sha256=sha(Path(__file__).read_bytes()))
    path.write_text(json.dumps(manifest, indent=2)+'\n')
    print('Generated', len(ranges), 'disjoint case-word ranges; no reference outputs stored.')


if __name__ == '__main__':
    main()
